sealed class FoldPanel:Panel {
 readonly Button toggle;readonly Control content;readonly int expanded;readonly string title;public bool Open;
 public FoldPanel(string title,Control child,int height,DockStyle dock){this.title=title;content=child;expanded=height;Dock=dock;Height=30;toggle=new Button{Text="⌄ "+title,Dock=DockStyle.Top,Height=30,TextAlign=ContentAlignment.MiddleLeft,FlatStyle=FlatStyle.Flat,Padding=new Padding(8,0,0,0)};content.Dock=DockStyle.Fill;content.Visible=false;Controls.Add(content);Controls.Add(toggle);toggle.Click+=delegate{SetOpen(!Open);};}
 public void SetOpen(bool value){Open=value;content.Visible=value;Height=30+(value?expanded:0);toggle.Text=(value?"⌃ ":"⌄ ")+title;}
}
sealed class ResponsiveFilterBar:FlowLayoutPanel {
 bool resizing;
 public ResponsiveFilterBar(){Dock=DockStyle.Top;WrapContents=true;Padding=new Padding(6);Margin=new Padding(0);}
 protected override void OnLayout(LayoutEventArgs e){base.OnLayout(e);if(resizing||Width<50)return;resizing=true;try{int height=Controls.Cast<Control>().Where(c=>c.Visible).Select(c=>c.Bottom+c.Margin.Bottom).DefaultIfEmpty(28).Max()+Padding.Bottom;if(Height!=height)Height=height;}finally{resizing=false;}}
}
