 void EnableResponsiveFilters(Control root){foreach(var old in Tree(root).OfType<FlowLayoutPanel>().Where(p=>p.Dock==DockStyle.Top&&p.GetType()==typeof(FlowLayoutPanel)).ToList()){var parent=old.Parent;int index=parent.Controls.GetChildIndex(old);var bar=new ResponsiveFilterBar();var children=old.Controls.Cast<Control>().ToList();for(int i=0;i<children.Count;i++){var child=children[i];if(child is Label&&i+1<children.Count){var group=new FlowLayoutPanel{AutoSize=true,AutoSizeMode=AutoSizeMode.GrowAndShrink,WrapContents=false,Margin=new Padding(3)};group.Controls.Add(child);group.Controls.Add(children[++i]);bar.Controls.Add(group);}else bar.Controls.Add(child);}parent.Controls.Remove(old);parent.Controls.Add(bar);parent.Controls.SetChildIndex(bar,index);old.Dispose();if(parent is Panel&&parent!=overviewScores&&parent.Dock==DockStyle.Top&&!(parent is FoldPanel)){Action fit=()=>{int height=bar.Height+parent.Controls.Cast<Control>().Where(x=>x!=bar&&x.Dock==DockStyle.Bottom).Sum(x=>x.Height)+parent.Padding.Vertical;if(parent.Height!=height)parent.Height=height;};bar.SizeChanged+=delegate{fit();};foreach(Control bottom in parent.Controls.Cast<Control>().Where(x=>x.Dock==DockStyle.Bottom))bottom.SizeChanged+=delegate{fit();};fit();}}}
